    def _normalize_trace(self, trace: Iterable[Any]) -> List[Any]:
        t = list(trace)
        if self.trace_len > 0 and len(t) > self.trace_len:
            t = t[-self.trace_len:]
        if self.trace_len > 0 and len(t) < self.trace_len:
            t = [P1_PAD_TOKEN] * (self.trace_len - len(t)) + t
        return t

